import { OnecTool } from './onecTool'
import * as core from '@actions/core'
import { logger } from '../onegetjs/logger'
import { exec } from '@actions/exec'
import { downloadRelease } from '../onegetjs'
import { compareVersions } from 'compare-versions'
import { DistributiveType } from '../onegetjs/model'
import { findFiles } from '../fileLocator'

export class Platform83 extends OnecTool {
  INSTALLED_CACHE_PRIMARY_KEY = 'onec'
  version: string
  cache_: string[]
  platform: string
  constructor(version: string, platform: string) {
    super()
    this.version = version
    this.platform = platform
    this.cache_ = this.getCacheDirs()
  }

  useNewInstaller(): boolean {
    return compareVersions(this.version, '8.3.20') >= 0
  }

  async download(): Promise<void> {
    let platformType = this.getPlatformType()

    let installerType: DistributiveType = 'full'

    if (platformType == 'linux' && !this.useNewInstaller()) {
      installerType = 'clientOrServer'
      platformType = 'deb'
    }

    await downloadRelease(
      {
        project: getProjectName(this.version),
        version: this.version,
        osName: platformType,
        architecture: 'x64',
        type: installerType
      },
      this.getInstallersPath(),
      true
    )

    logger.info(`onec was downloaded`)
  }

  async install(): Promise<void> {
    const installerPattern = this.isWindows()
      ? 'setup.exe'
      : this.useNewInstaller()
        ? 'setup-full'
        : '*.deb'

    const path = this.getInstallersPath()

    const files = await findFiles(`${path}/**/${installerPattern}*`)
    logger.info(`found ${files}`)

    if (this.isLinux() && this.useNewInstaller()) {
      await exec('sudo', [
        files[0],
        '--mode',
        'unattended',
        '--enable-components',
        'server,client_full',
        '--disable-components',
        'client_thin,client_thin_fib,ws'
      ])
    } else if (this.isLinux()) {
      for await (const mask of ['common', 'server', 'thin-client', 'client']) {
        const files = await findFiles(`${path}/1c-enterprise83-${mask}_*.deb`)

        if (files.length !== 0) {
          await exec('sudo', ['dpkg', '-i', '--force-all', `${files[0]}`])
        } else {
          logger.warning(
            `File not found for ${mask} (mask: 1c-enterprise83-${mask}_*.deb)`
          )
        }
      }
    } else if (this.isWindows()) {
      await exec(files[0], [
        '/l',
        'ru',
        '/S',
        'server=1',
        'thinclient=1',
        'RU=1',
        'EN=1',
        'LANGUAGES=RU,EN',
        '/quiet',
        '/qn',
        'INSTALLSRVRASSRVC=0',
        '/norestart'
      ])
    } else {
      core.setFailed(`Unrecognized os ${this.platform}`)
    }
  }

  getCacheDirs(): string[] {
    if (this.isWindows()) {
      return ['C:/Program Files/1cv8']
    } else if (this.isLinux() && this.useNewInstaller()) {
      return ['/opt/1cv8']
    } else if (this.isLinux()) {
      return ['/opt/1C/v8.3']
    } else if (this.isMac()) {
      return ['/opt/1cv8'] // /Applications/1cv8.localized/8.3.21.1644/ but only .app
    } else {
      throw new Error('Not supported on this OS type')
    }
  }

  getRunFileNames(): string[] {
    if (this.isWindows()) {
      return ['1cv8.exe']
    } else {
      return ['1cv8']
    }
  }
}

function getProjectName(version: string): string {
  const versionParts = version.split('.')
  if (versionParts.length < 2) {
    throw new Error(`Invalid version format: ${version}`)
  }
  const major = parseInt(versionParts[0], 10)
  const minor = parseInt(versionParts[1], 10)

  if (major === 8 && minor === 5) {
    return 'Platform85'
  } else if (major === 8 && minor === 3) {
    return 'Platform83'
  } else {
    throw new Error(
      `Unsupported version: ${version}. Supported versions: 8.3.* and 8.5.*`
    )
  }
}
